INSERT INTO [dbo].[MauTraLoi] ([MaMau], [MaDonVi], [TieuDe], [NoiDung], [MaTK_Tao], [HoatDong]) VALUES
    (1, 2, N'Mẫu trả lời về Đăng ký học phần trễ hạn', N'Chào em, Phòng Đào tạo đã nhận được câu hỏi. Đối với trường hợp đăng ký học phần trễ hạn vì lý do bất khả kháng, em vui lòng nộp kèm minh chứng hợp lệ (giấy viện, xác nhận khoa) trong giờ hành chính tại Bàn 03 Phòng Đào tạo.', 52, 1);
