    (18, 35, 1, 2, 19, N'Em muốn hỏi về điều kiện rút học phần trong học kỳ này', N'Dạ thưa Thầy/Cô, do lịch thi giữa kỳ bị trùng với đợt thực tập của doanh nghiệp, em muốn rút học phần Nhập môn Trí tuệ Nhân tạo thì hạn chót là khi nào và có được hoàn học phí không ạ? Em xin cảm ơn.', 0, N'Dong', '2026-09-20 15:30:42.663', '2026-10-02 22:30:00.062', '2026-09-23 17:00:00.000', '2026-09-28 17:00:00.000', '2026-09-20 19:30:42.663', '2026-09-21 10:30:42.663', '2026-09-21 10:30:42.663', '2026-09-28 15:30:42.663', '2026-10-02 22:30:00.029', N'Hệ thống tự động đóng sau 7 ngày không có câu hỏi bổ sung.', 1),
    (19, 36, 7, 1, 18, N'Tư vấn định hướng theo mảng Data Engineering hay Data Science', N'Em hiện là sinh viên năm 3 ngành Khoa học Dữ liệu. Em đang phân vân giữa việc theo hướng xây dựng pipeline dữ liệu (Data Engineer) hay đi sâu vào mô hình Machine Learning/AI. Mong Thầy/Cô Khoa CNTT định hướng giúp em về cơ hội việc làm thực tế tại các công ty hiện nay ạ.', 0, N'DangXuLy', '2026-09-21 13:30:42.663', '2026-09-21 19:08:57.167', '2026-09-23 13:30:42.663', '2026-09-23 13:30:42.663', '2026-09-21 19:08:57.147', NULL, NULL, NULL, NULL, NULL, 1),
