INSERT INTO [dbo].[CauHoiFAQ] ([MaFAQ], [CauHoi], [CauTraLoi], [MaLinhVuc], [MaYeuCauNguon], [TuKhoa], [LuotXem], [TrangThai], [MaTK_DeXuat], [MaTK_Duyet], [NgayDuyet], [NgayTao]) VALUES
    (2, N'Làm thế nào để đăng ký học phần vượt quá số tín chỉ quy định?', N'Sinh viên có điểm trung bình chung tích lũy từ 3.2 trở lên có thể làm đơn xin đăng ký vượt tối đa 3 tín chỉ so với quy định chuẩn. Đơn gửi về Phòng Đào tạo trong tuần đầu tiên của đợt hiệu chỉnh đăng ký.', 1, NULL, N'vượt tín chỉ, đăng ký môn, học vụ', 47, N'HienThi', 52, 52, '2026-09-21 15:30:42.663', '2026-09-21 15:30:42.663'),
    (3, N'Quy trình xin cấp giấy xác nhận sinh viên để hoãn nghĩa vụ quân sự?', N'Sinh viên đăng nhập vào cổng thông tin sinh viên, chọn mục ''Dịch vụ trực tuyến -> Đăng ký cấp giấy xác nhận'', chọn lý do ''Tạm hoãn NVQS''. Sau 02 ngày làm việc, sinh viên đến Phòng CTSV nhận giấy đóng dấu gốc hoặc tải bản ký số điện tử.', 3, NULL, N'giấy xác nhận, NVQS, thủ tục sinh viên', 76, N'HienThi', 52, 52, '2026-09-21 15:30:42.663', '2026-09-21 15:30:42.663');
INSERT INTO [dbo].[BaiVietHuongDan] ([MaBaiViet], [TieuDe], [TomTat], [NoiDung], [TuKhoa], [MaLinhVuc], [MaTK_Admin], [LuotXem], [NgayTao], [NgayDang], [MaTK_Duyet], [TrangThai]) VALUES
    (1, N'Cẩm nang Sinh viên: Toàn tập về quy chế đào tạo theo hệ thống tín chỉ', N'Tổng hợp các quy định quan trọng về đăng ký học phần, rút học phần, cảnh báo học vụ và điều kiện xét tốt nghiệp đúng hạn.', N'Hệ thống đào tạo theo tín chỉ cho phép sinh viên chủ động kế hoạch học tập. Trong mỗi học kỳ chính, sinh viên phải đăng ký tối thiểu 14 tín chỉ (trừ học kỳ cuối). Để được xét học bổng, sinh viên cần tích lũy tối thiểu 15 tín chỉ và không có học phần nào bị điểm F.', N'quy chế, tín chỉ, học vụ, tốt nghiệp', 1, 52, 183, '2026-09-21 15:30:42.663', '2026-09-21 15:30:42.663', 52, N'XuatBan'),
    (2, N'Hướng dẫn chuẩn bị hồ sơ xét học bổng khuyến khích học tập kỳ 1', N'Các mốc thời gian, biểu mẫu và quy trình nộp hồ sơ xét học bổng dành cho sinh viên có thành tích xuất sắc.', N'Học bổng khuyến khích học tập được xét dựa trên kết quả học tập và điểm rèn luyện của học kỳ trước liền kề. Sinh viên thuộc diện xét duyệt cần theo dõi thông báo từ Phòng Công tác Sinh viên và kiểm tra tài khoản ngân hàng liên kết.', N'học bổng, khuyến khích học tập, CTSV', 2, 52, 99, '2026-09-21 15:30:42.663', '2026-09-21 15:30:42.663', 52, N'XuatBan');
